CREATE TABLE ibexa_url (id INT AUTO_INCREMENT NOT NULL, created INT DEFAULT 0 NOT NULL, is_valid INT DEFAULT 1 NOT NULL, last_checked INT DEFAULT 0 NOT NULL, modified INT DEFAULT 0 NOT NULL, original_url_md5 VARCHAR(32) DEFAULT '' NOT NULL, url LONGTEXT DEFAULT NULL, INDEX ibexa_url_url (url(191)), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
